Running command: set -e; 
if [ ! -f /workspace/mainpage.html ]; then echo "ERROR: /workspace/mainpage.html not found" >&2; exit 1; fi; 
ln -sf mainpage.html /workspace/index.html; 
if [ -f /workspace/server_8000.pid ]; then OLD_PID=$(cat /workspace/server_8000.pid); if kill -0 "$OLD_PID" 2>/dev/null; then kill "$OLD_PID" 2>/dev/null || true; fi; rm -f /workspace/server_8000.pid; fi; 
cd /workspace; 
python3 -m http.server 8000 > /workspace/server_8000.log 2>&1 & 
echo $! > /workspace/server_8000.pid; 
sleep 1; 
echo "Server started on http://localhost:8000"; 
echo "PID=$(cat /workspace/server_8000.pid)"; 
sed -n '1,50p' /workspace/server_8000.log

